(function(root){'use strict';const data={"y11-blood-components":{"title":"Blood: plasma and formed elements","alt":"Blood: plasma and formed elements. This figure shows three test tubes with a red and yellow liquid in them. The left panel shows normal blood, the center panel shows anemic blood and the right panel shows polycythemic blood.","src":"assets/human-biology/year11/y11-blood-components.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/18-1-functions-of-blood/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2019/07/1901_Composition_of_Blood.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Distinguish plasma, erythrocytes, leukocytes and platelets. Relate each component to transport, defence or clotting. A separated sample displays proportions but does not make every cell type equally abundant.","width":1517,"height":950,"sourceCaption":"Figure 18.1.1 .  Composition of Blood:  The cellular elements of blood include a vast number of erythrocytes and comparatively fewer leukocytes and platelets. Plasma is the fluid in which the formed elements are suspended. A sample of blood spun in a centrifuge reveals that plasma is the least dense component. It floats at the top of the tube separated from the densest elements, the erythrocytes, which are separated by a buffy coat of leukocytes and platelets. Hematocrit is the percentage of the total sample that is comprised of erythrocytes. Depressed and elevated hematocrit levels are shown for comparison."},"y11-tissues":{"title":"Four primary human tissue types","alt":"Four primary human tissue types. This diagram shows the silhouette of a female surrounded by four micrographs of tissue. Each micrograph has arrows pointing to the organs where that tissue is found. The upper left micrograph shows nervous tissue that is whitish with several large, purple, irregularly-shaped neurons embedded throughout. Nervous tissue is found in the brain, spinal cord and nerves. The upper right micrograph shows muscle tissue that is red with elongated cells and prominent, purple nuclei. Cardiac muscle is found in the heart. Smooth muscle is found in muscular internal organs, such as the stomach. Skeletal muscle is found in parts that are moved voluntarily, such as the arms. The lower left micrograph shows epithelial tissue. This tissue is purple with many round, purple cells with dark purple nuclei. Epithelial tissue is found in the lining of GI tract organs and other hollow organs such as the small intestine. Epithelial tissue also composes the outer layer of the skin, known as the epidermis. Finally, the lower right micrograph shows connective tissue, which is composed of very loosely packed purple cells and fibers. There are large open spaces between clumps of cells and fibers. Connective tissue is found in the leg within fat and other soft padding tissue as well as bones and tendons.","src":"assets/human-biology/year11/y11-tissues.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/4-1-types-of-tissues/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2019/07/401_Types_of_Tissue.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Compare the micrographs of epithelial, connective, muscle and nervous tissue. Identify a structure–function relationship for each and remember that an organ contains several tissue types.","width":1070,"height":1135,"sourceCaption":"Figure 4.1.1 – The Four Primary Tissue Types:  Examples of nervous tissue, epithelial tissue, muscle tissue, and connective tissue found throughout the human body. Clockwise from nervous tissue, LM × 872, LM × 282, LM × 460, LM × 800. (Micrographs provided by the Regents of University of Michigan Medical School © 2012)"},"y11-cell":{"title":"Human cell: organelles and compartments","alt":"Human cell: organelles and compartments. This diagram shows an animal cell with all the intracellular organelles labeled.","src":"assets/human-biology/year11/y11-cell.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/3-2-the-cytoplasm-and-cellular-organelles/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2019/07/0312_Animal_Cell_and_Components.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Locate the nucleus, mitochondria, rough ER, Golgi and vesicles. Trace a secreted protein through the relevant compartments. This is a composite cell model, not a picture of every specialised human cell.","width":813,"height":645,"sourceCaption":"Figure 3.2.1 – Prototypical Human Cell:  While this image is not indicative of any one particular human cell, it is a prototypical example of a cell containing the primary organelles and internal structures."},"y11-abo":{"title":"ABO antigens and plasma antibodies","alt":"ABO antigens and plasma antibodies. This table shows the different blood types, the antibodies in plasma, the antigens in the red blood cell, and the blood compatible blood types in an emergency.","src":"assets/human-biology/year11/y11-abo.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/18-6-blood-typing/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/1913_ABO_Blood_Groups.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Match A and B antigens on erythrocytes with the usual plasma antibodies. Explain why incompatible donor red cells can agglutinate; red-cell transfusion compatibility differs from plasma compatibility and requires clinical matching. This is a simplified red-cell compatibility model; plasma compatibility and clinical crossmatching require separate consideration.","width":1812,"height":1392,"sourceCaption":"Figure 18.6.3 – ABO Blood Group:  This chart summarizes the characteristics of the blood types in the ABO blood group. See the text for more on the concept of a universal donor or recipient."},"y11-mitochondria":{"title":"Mitochondrion: membranes, cristae and matrix","alt":"Mitochondrion: membranes, cristae and matrix. This figure shows the structure of a mitochondrion. The inner and outer membrane, the cristae and the intermembrane space are labeled. The right panel shows a micrograph with the structure of a mitochondrion in detail.","src":"assets/human-biology/year11/y11-mitochondria.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/3-2-the-cytoplasm-and-cellular-organelles/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/0315_Mitochondrion_new.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Locate the outer membrane, folded inner membrane and matrix. Relate compartmentalisation and membrane area to aerobic ATP production; the drawing is not a scale measurement.","width":1900,"height":843,"sourceCaption":"Figure 3.2.4 – Mitochondrion:  The mitochondria are the energy-conversion factories of the cell. (a) A mitochondrion is composed of two separate lipid bilayer membranes. Along the inner membrane are various molecules that work together to produce ATP, the cell’s major energy currency. (b) An electron micrograph of mitochondria (EM × 236,000). (Micrograph provided by the Regents of University of Michigan Medical School © 2012)"},"y11-circulation":{"title":"Pulmonary and systemic double circulation","alt":"Pulmonary and systemic double circulation. The top panel shows the human heart with the arteries and veins labeled. The bottom panel shows the human circulatory system.","src":"assets/human-biology/year11/y11-circulation.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/19-1-heart-anatomy/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2003_Dual_System_of_Human_Circulation_revised.png","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Follow one complete circuit from the right ventricle through lungs, left heart, body tissues and right atrium. Define arteries and veins by direction relative to the heart rather than by oxygen content.","width":1715,"height":1900,"sourceCaption":"Figure 19.1.2 – Dual System of the Human Blood Circulation:  Blood flows from the right atrium to the right ventricle, where it is pumped into the pulmonary circuit. The blood in the pulmonary artery branches is low in oxygen but relatively high in carbon dioxide. Gas exchange occurs in the pulmonary capillaries (oxygen into the blood, carbon dioxide out), and blood high in oxygen and low in carbon dioxide is returned to the left atrium. From here, blood enters the left ventricle, which pumps it into the systemic circuit. Following exchange in the systemic capillaries (oxygen and nutrients out of the capillaries and carbon dioxide and wastes in), blood returns to the right atrium and the cycle is repeated."},"y11-heart-anatomy":{"title":"Heart chambers, septum, valves and major vessels","alt":"Heart chambers, septum, valves and major vessels. In this figure the top panel shows the image of the heart with the major parts labeled. The bottom left panel shows a photo of the heart with the surface layer peeled off. The images on the bottom right show detailed musculature inside the heart.","src":"assets/human-biology/year11/y11-heart-anatomy.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/19-1-heart-anatomy/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2008_Internal_Anatomy_of_the_HeartN.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Trace blood from the venae cavae through both sides of the heart to the aorta. Explain how the septum and one-way valves support two connected circuits. Diagrammatic colours indicate relative oxygenation, not actual blue blood.","width":1656,"height":1159,"sourceCaption":"Figure 19.1.8 – Internal Structures of the Heart:  This anterior view of the heart shows the four chambers, the major vessels and their early branches, as well as the four valves. The presence of the pulmonary trunk and aorta covers the interatrial septum, and the atrioventricular septum is cut away to show the atrioventricular valves."},"y11-carbohydrate-digestion":{"title":"Carbohydrate digestion: polymer to absorbable sugars","alt":"Carbohydrate digestion: polymer to absorbable sugars. This flow chart shows the steps in digestion of carbohydrates. The different levels shown are starch and glycogen, disaccharides and monosaccharides. Under each type of sugar, examples and the enzymes responsible for digestion are listed.","src":"assets/human-biology/year11/y11-carbohydrate-digestion.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/23-7-chemical-digestion-and-absorption-a-closer-look/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2427_Carbon_Digestion.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Trace starch breakdown through intermediate carbohydrates to monosaccharides. Identify enzyme-mediated hydrolysis as chemical digestion, then separate breakdown in the lumen from absorption across the epithelium.","width":570,"height":621,"sourceCaption":"Figure 23.7.2 – Carbohydrate Digestion Flow Chart:  Carbohydrates are broken down into their monomers in a series of steps."},"y11-peristalsis":{"title":"Peristalsis propels material through the gut","alt":"Peristalsis propels material through the gut. This image shows the peristaltic movement of food. In the left image, the food bolus is towards the top of the esophagus and arrows pointing downward show the direction of movement of the peristaltic wave. In the center image, the food bolus and the wave movement are closer to the center of the esophagus and in the right image, the bolus and the wave are close to the bottom end of the esophagus.","src":"assets/human-biology/year11/y11-peristalsis.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/23-2-digestive-system-processes-and-regulation/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2404_PeristalsisN.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Follow the sequence of smooth-muscle contraction and relaxation around a bolus. Explain propulsion through the tube; it is a coordinated muscular process rather than food simply falling under gravity.","width":542,"height":405,"sourceCaption":"Figure 23.2.1 – Peristalsis:  Peristalsis moves food through the digestive tract with alternating waves of muscle contraction and relaxation."},"y11-lymph-capillaries":{"title":"Tissue fluid and lymphatic capillaries","alt":"Tissue fluid and lymphatic capillaries. This image shows the lymph capillaries in the tissue spaces, and a magnified image shows the interstitial fluid and the lymph vessels. The major parts are labeled.","src":"assets/human-biology/year11/y11-lymph-capillaries.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/21-1-anatomy-of-the-lymphatic-and-immune-systems/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2202_Lymphatic_Capillaries.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Trace excess tissue fluid into blind-ended lymphatic capillaries and then towards larger lymph vessels. Connect fluid return with the circulation; lymph formation is not the same as all blood leaking out of capillaries.","width":1008,"height":583,"sourceCaption":"Figure 21.1.2 – Lymphatic Capillaries:  Lymphatic capillaries are interlaced with the arterioles and venules of the cardiovascular system. Collagen fibers anchor a lymphatic capillary in the tissue (inset). Interstitial fluid slips through spaces between the overlapping endothelial cells that compose the lymphatic capillary."},"y11-lipid-absorption":{"title":"Lipid absorption and entry into lacteals","alt":"Lipid absorption and entry into lacteals. This diagram shows how lipids are absorbed from the lumen of the intestine into the lacteals. The fatty acid micelles are shown to enter the epithelial cell and form chylomicrons inside the Golgi apparatus. Then, the chylomicrons are extruded from the epithelial cell and are taken up by the lacteals.","src":"assets/human-biology/year11/y11-lipid-absorption.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/23-7-chemical-digestion-and-absorption-a-closer-look/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2431_Lipid_Absorption.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Trace products from intestinal lumen into an epithelial cell, packaging into chylomicrons and entry into a lacteal. The figure describes a major long-chain lipid route rather than every lipid molecule taking an identical path.","width":640,"height":827,"sourceCaption":"Figure 23.7.6 – Lipid Absorption:  Unlike amino acids and simple sugars, lipids are transformed as they are absorbed through epithelial cells."},"y11-arteries":{"title":"Arterial and arteriolar wall structure","alt":"Arterial and arteriolar wall structure. The left panel shows the cross-section of an elastic artery, the middle panel shows the cross section of a muscular artery, and the right panel shows the cross-section of an arteriole.","src":"assets/human-biology/year11/y11-arteries.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/20-1-structure-and-function-of-blood-vessels/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2103_Muscular_and_Elastic_Artery_Arteriole.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Compare elastic tissue, smooth muscle and lumen dimensions in the labelled vessels. Explain how vessel structure supports pressure handling and distribution, without assuming the drawings use identical scales.","width":1900,"height":484,"sourceCaption":"Figure 20.1.3 – Types of Arteries and Arterioles:  Comparison of the walls of an elastic artery, a muscular artery, and an arteriole is shown. In terms of scale, the diameter of an arteriole is measured in micrometers compared to millimeters for elastic and muscular arteries."},"y11-villi":{"title":"Small-intestinal folds, villi and microvilli","alt":"Small-intestinal folds, villi and microvilli. Illustration (a) shows the histological cross-section of the small intestine. The left panel shows a small region of the small intestine, along with the blood vessels and the muscle layers. The middle panel shows a magnified view of a small region of the small intestine, highlighting the absorptive cells, the lacteal and the goblet cells. The right panel shows a further magnified view of the epithelial cells including the microvilli. Illustrations (b) shows a micrograph of the circular folds, and illustration (c) shows a micrograph of the villi. Illustration (d) shows an electron micrograph of the microvilli.","src":"assets/human-biology/year11/y11-villi.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/23-6-the-small-and-large-intestines/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2418_Histology_Small_IntestinesN.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Compare the successive levels of increased absorptive surface. Locate epithelium, capillaries and lacteal, then explain why most soluble nutrients and many lipid products enter different transport routes.","width":1079,"height":824,"sourceCaption":"Figure 23.6.2 – Histology of the Small Intestine:  (a) The absorptive surface of the small intestine is vastly enlarged by the presence of circular folds, villi, and microvilli. (b) Micrograph of the circular folds. (c) Micrograph of the villi. (d) Electron micrograph of the microvilli. From left to right, LM x 56, LM x 508, EM x 196,000. (credit b-d: Micrograph provided by the Regents of University of Michigan Medical School © 2012)"},"y11-digestive-tract":{"title":"Digestive tract and accessory organs","alt":"Digestive tract and accessory organs. This diagram shows the digestive system of a human being, with the major organs labeled.","src":"assets/human-biology/year11/y11-digestive-tract.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/23-1-overview-of-the-digestive-system/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2019/07/2401_Components_of_the_Digestive_System_revised-e1568240853144.png","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Trace food from mouth to anus and distinguish the alimentary canal from the salivary glands, liver, gall bladder and pancreas. Identify where secretions enter rather than suggesting food passes through every accessory organ.","width":1589,"height":1900,"sourceCaption":"Figure 23.1.1 – Components of the Digestive System:  All digestive organs play integral roles in the life-sustaining process of digestion."},"y11-synovial-joint":{"title":"Synovial joint: cartilage, capsule and fluid","alt":"Synovial joint: cartilage, capsule and fluid. This figure shows a synovial joint. The cavity between two bones contains the synovial fluid which lubricates the two joints.","src":"assets/human-biology/year11/y11-synovial-joint.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/9-4-synovial-joints/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2019/07/907_Synovial_Joints.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Identify articular cartilage, joint cavity, synovial membrane and capsule. Link lubrication and smooth surfaces with low-friction movement, and distinguish a ligament connecting bones from a tendon connecting muscle to bone.","width":1425,"height":1578,"sourceCaption":"Figure 9.4.1 – Synovial Joints:  Synovial joints allow for smooth movements between the adjacent bones. The joint is surrounded by an articular capsule that defines a joint cavity filled with synovial fluid. The articulating surfaces of the bones are covered by a thin layer of articular cartilage. Ligaments support the joint by holding the bones together and resisting excess or abnormal joint motions."},"y11-bone":{"title":"Compact bone: osteons, lamellae and canals","alt":"Compact bone: osteons, lamellae and canals. A generic long bone is shown at the top of this illustration. The bone is split in half lengthwise to show its internal anatomy. The outer gray covering of the bone is labeled the periosteum. Within the periosteum is a thin layer of compact bone. The compact bone surrounds a central cavity called the medullary cavity. The medullary cavity is filled with spongy bone at the two epiphyses. A callout box shows that the main image is zooming in on the compact bone on the left side of the bone. On the main image, the periosteum is being peeled back to show its two layers. The outer layer of the periosteum is the outer fibrous layer. This layer has a periosteal artery and a periosteal vein running along its outside edge. The inner layer of the periosteum is labeled the inner osteogenic layer. The compact bone lies to the right of the periosteum and occupies the majority of the main image. Two flat layers of compact bone line the inner surface of the ostegenic periosteum. These sheets of compact bone are called the circumferential lamellae. The majority of the compact bone has lamellae running perpendicular to that of the circumferential lamellae. These concentric lamellae are arranged in a series of concentric tubes. There are small cavities between the layers of concentric lamellae called lacunae. The centermost concentric lamella surrounds a hollow central canal. A blue vein, a red artery, a yellow nerve and a green lymph vessel run vertically through the central canal. A set of concentric lamellae, its associated lacunae and the vessels and nerves of the central canal are collectively called an osteon. The front edge of the diagram shows a longitudinal cross section of one of the osteons. The vessels and nerve are visible running through the center of the osteon throughout its length. In addition, blood vessels can run from the periosteum through the sides of the osteons and connect with the vessels of the central canal. The blood vessels travel through the sides of the osteons via a perforating canal. The open areas between neighboring osteons are also filled with compact bone. This “filler” bone is referred to as the interstitial lamellae. At the far right of the compact bone, the edge of the spongy bone is visible. The spongy bone is a series of crisscrossing bony arches called trabeculae. There are many open spaces between the trabeculae, giving the spongy bone its sponge-like appearance.","src":"assets/human-biology/year11/y11-bone.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/6-3-bone-structure/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/624_Diagram_of_Compact_Bone_revised.png","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Locate osteons, central canals, lamellae and osteocytes. Explain how a mineralised matrix provides support while canals and canaliculi permit living bone cells to obtain materials.","width":1405,"height":1665,"sourceCaption":"Figure 6.3.6 – Diagram of Compact Bone:  (a) This cross-sectional view of compact bone shows several osteons, the basic structural unit of compact bone. (b) In this micrograph of the osteon, you can see the concentric lamellae around the central canals. LM × 40. (Micrograph provided by the Regents of University of Michigan Medical School © 2012)"},"y11-respiratory-tract":{"title":"Respiratory tract: air pathway to the lungs","alt":"Respiratory tract: air pathway to the lungs. This figure shows the upper half of the human body. The major organs in the respiratory system are labeled.","src":"assets/human-biology/year11/y11-respiratory-tract.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/22-1-organs-and-structures-of-the-respiratory-system/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2019/07/2301_Major_Respiratory_Organs.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Trace air through the nasal cavity, pharynx, larynx, trachea, bronchi and smaller passages. Distinguish conducting regions from the gas-exchange surfaces rather than treating every part of the airway as an alveolus.","width":1900,"height":1597,"sourceCaption":"Figure 22.1.1 – Major Respiratory Structures:  The major respiratory structures span the nasal cavity to the diaphragm."},"y11-muscle-fibre":{"title":"Skeletal muscle fibre and myofibrils","alt":"Skeletal muscle fibre and myofibrils. This figure shows the structure of the muscle fibers. In the top panel, a sarcolemma is shown with the major parts labeled. In the bottom panel, a magnified view of a single myofibril is shown and the major parts are labeled.","src":"assets/human-biology/year11/y11-muscle-fibre.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/10-2-skeletal-muscle/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/1022_Muscle_Fibers_small_revised-1.png","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Trace organisation from a muscle fibre to myofibrils and repeated sarcomeres. Distinguish a whole muscle, a fascicle and a muscle cell rather than using those terms interchangeably.","width":1603,"height":1295,"sourceCaption":"Figure 10.2.2 – Muscle Fiber:  A skeletal muscle fiber is surrounded by a plasma membrane called the sarcolemma, which contains sarcoplasm, the cytoplasm of muscle cells. A muscle fiber is composed of many myofibrils, which contain sarcomeres with light and dark regions that give the cell its striated appearance."},"y11-sarcomere":{"title":"Sarcomere: thick and thin filament arrangement","alt":"Sarcomere: thick and thin filament arrangement. This figure shows the structure of thick and thin filaments. On the top of the image a sarcomere is shown with the H zone, Z line and M lines labeled. To the right of the bottom panel, the structure of the thick filament is shown in detail. To the left of the bottom panel, the structure of a thin filament is shown in detail.","src":"assets/human-biology/year11/y11-sarcomere.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/10-2-skeletal-muscle/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/1003_Thick_and_Thin_Filaments_revised.png","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Locate Z discs, actin, myosin and the central region. Predict which distances or zones change when overlap increases. The filaments slide relative to each other rather than becoming shorter.","width":1900,"height":1714,"sourceCaption":"Figure 10.2.3 – The Sarcomere:  The sarcomere, the region from one Z-disc to the next Z-disc, is the functional unit of a skeletal muscle fiber."},"y11-sliding-filaments":{"title":"Sliding-filament model of contraction","alt":"Sliding-filament model of contraction. ","src":"assets/human-biology/year11/y11-sliding-filaments.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/10-2-skeletal-muscle/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/10.2.4-replacement.png","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Compare relaxed and shortened sarcomeres. Trace the change in filament overlap and Z-disc separation; connect the model to cross-bridge activity and ATP, which are not fully shown by a static comparison.","width":1900,"height":1069,"sourceCaption":"Figure 10.2.4 – The Sliding Filament Model of Muscle Contraction:  When a sarcomere shortens, the Z-discs move closer together, and the I band becomes smaller. The A band stays the same width. At full contraction, the thin and thick filaments have the most amount of overlap."},"y11-joint-types":{"title":"Types of synovial joints and permitted movements","alt":"Types of synovial joints and permitted movements. This composite image shows the different types of synovial joints in the body. In the center of the figure is a skeleton, and call outs from each joint show their names and locations.","src":"assets/human-biology/year11/y11-joint-types.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/9-4-synovial-joints/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/909_Types_of_Synovial_Joints-scaled-1.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Compare hinge, pivot, ball-and-socket and other illustrated joint forms. Explain how surface shape permits particular movements; joint structure and movement range are related classification approaches.","width":1594,"height":1900,"sourceCaption":"Figure 9.4.3 – Types of Synovial Joints:  The six types of synovial joints allow the body to move in a variety of ways. (a) Pivot joints allow for rotation around an axis, such as between the first and second cervical vertebrae, which allows for side-to-side rotation of the head. (b) The hinge joint of the elbow works like a door hinge. (c) The articulation between the trapezium carpal bone and the first metacarpal bone at the base of the thumb is a saddle joint. (d) Plane joints, such as those between the tarsal bones of the foot, allow for limited gliding movements between bones. (e) The radiocarpal joint of the wrist is a condyloid joint. (f) The hip and shoulder joints are the only ball-and-socket joints of the body."},"y11-cleavage":{"title":"Cleavage from zygote to blastocyst","alt":"Cleavage from zygote to blastocyst. This figure shows the different stages of cell divisions taking place before the embryo is formed. The top panel shows the cell divisions occurring in the uterine tube and the bottom panel shows the cell divisions occurring in the uterus.","src":"assets/human-biology/year11/y11-cleavage.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/28-2-embryonic-development/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2019/07/2903_Preembryonic_Cleavages-02-1.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Follow repeated divisions through early cell stages to a blastocyst. Distinguish increasing cell number from substantial growth in total conceptus size during early cleavage.","width":1549,"height":1359,"sourceCaption":"Figure 28.2.1 – Pre-Embryonic Cleavages:  Pre-embryonic cleavages make use of the abundant cytoplasm of the conceptus as the cells rapidly divide without changing the total volume."},"y11-female-reproduction":{"title":"Ovaries, uterine tubes, uterus and endometrium","alt":"Ovaries, uterine tubes, uterus and endometrium. This diagram shows the uterus and ovaries in the center. To the left is a micrograph showing the ultrastructure of the ovaries and to the right is a micrograph showing the ultrastructure of the uterus.","src":"assets/human-biology/year11/y11-female-reproduction.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/27-1-anatomy-of-sexual-systems/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/Figure_28_02_06.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Locate ovary, uterine tube, uterus, cervix and the layers shown. Trace the likely route of an oocyte and distinguish the usual site of fertilisation from the site of implantation.","width":818,"height":393,"sourceCaption":"Figure 27.1.2 – Ovaries, Uterine Tubes, and Uterus:  This anterior view shows the relationship of the ovaries, uterine tubes (oviducts), and uterus. From left to right, LM × 400, LM × 20. (Micrographs provided by the Regents of University of Michigan Medical School © 2012)"},"y11-testis":{"title":"Testis: seminiferous tubules and sperm transport","alt":"Testis: seminiferous tubules and sperm transport. This diagram shows the cross section of the testis.","src":"assets/human-biology/year11/y11-testis.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/27-1-anatomy-of-sexual-systems/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/Figure_28_01_03.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Locate the seminiferous tubules and ducts leading towards the epididymis. Relate tissue organisation to sperm production and transport; production of sperm and secretion of testosterone involve different cell roles.","width":743,"height":686,"sourceCaption":"Figure 27.1.6 – Anatomy of a Testis:  This sagittal view shows seminiferous tubules, the site of sperm production. Formed sperm are transferred to the epididymis, where they mature. They leave the epididymis during an ejaculation via the ductus deferens ."},"y11-male-reproduction":{"title":"Male reproductive anatomy and sperm pathway","alt":"Male reproductive anatomy and sperm pathway. This figure shows the different organs in the male reproductive system. The top panel shows the side view of a man and an uncircumcised and a circumcised penis. The bottom panel shows the lateral view of the male reproductive system and the major parts are labeled.","src":"assets/human-biology/year11/y11-male-reproduction.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/27-1-anatomy-of-sexual-systems/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/Figure_28_01_01.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Trace the pathway from testis through epididymis, vas deferens, ejaculatory duct and urethra. Distinguish the sites of sperm production, maturation and addition of accessory-gland secretions.","width":805,"height":876,"sourceCaption":"Figure 27.1.5 – Penis and Testes:  The structures of this reproductive system often include the testes, the epididymides, the penis, and the ducts and glands that produce and carry semen. Sperm exit the scrotum through the ductus deferens, which is bundled in the spermatic cord. The seminal vesicles and prostate gland add fluids to the sperm to create semen."},"y11-ventilation":{"title":"Inspiration and expiration: muscles, volume and pressure","alt":"Inspiration and expiration: muscles, volume and pressure. The left panel of this image shows a person inhaling air and the location of the chest muscles. The right panel shows the person exhaling air and the contraction of the thoracic cavity.","src":"assets/human-biology/year11/y11-ventilation.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/22-3-the-process-of-breathing/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2316_Inspiration_and_Expiration.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Compare diaphragm and thoracic movements during inspiration and quiet expiration. Link volume change to pressure difference and airflow. Air moves because of a pressure gradient, not because the lungs actively pull individual oxygen molecules in.","width":1900,"height":1404,"sourceCaption":"Figure 22.3.3 – Inspiration and Expiration:  Inspiration and expiration occur due to the expansion and contraction of the thoracic cavity, respectively."},"y11-alveoli":{"title":"Alveoli and the respiratory membrane","alt":"Alveoli and the respiratory membrane. This figure shows the detailed structure of the alveolus. The top panel shows the alveolar sacs and the bronchioles. The middle panel shows a magnified view of the alveolus, and the bottom panel shows a micrograph of the cross section of a bronchiole.","src":"assets/human-biology/year11/y11-alveoli.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/22-1-organs-and-structures-of-the-respiratory-system/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2310_Structures_of_the_Respiratory_Zone.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Locate alveolar epithelium and surrounding capillaries. Explain how a large surface and thin moist barrier support diffusion, with ventilation and blood flow maintaining useful gas gradients.","width":1900,"height":1121,"sourceCaption":"Figure 22.1.10 – Structures of the Respiratory Zone:  (a) The alveolus is responsible for gas exchange. (b) A micrograph shows the alveolar structures within lung tissue. LM × 178. (Micrograph provided by the Regents of University of Michigan Medical School © 2012)"},"y11-ivf":{"title":"IVF: collection, fertilisation and embryo transfer","alt":"IVF: collection, fertilisation and embryo transfer. This multi-part figure shows the different steps in in vitro fertilization. The top panel shows how the oocytes and the sperm are collected and prepared. The next panel shows the sperm and oocytes being mixed in a petri dish. The panel below that shows the fertilized zygote being prepared for implantation. The last panel shows the fertilized zygote being implanted into the uterus.","src":"assets/human-biology/year11/y11-ivf.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/28-1-fertilization/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2902_IVF-02-scaled-1.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Follow oocyte collection, laboratory fertilisation and transfer of an early embryo into the uterus. Distinguish fertilisation from implantation, and explain why the diagram does not establish that every transfer produces a pregnancy.","width":1300,"height":1900,"sourceCaption":"Figure 28.1.2 – IVF:  In vitro fertilization involves egg collection from the ovaries, fertilization in a petri dish, and the transfer of embryos into the uterus."},"y11-germ-layers":{"title":"Embryonic germ layers and tissue derivatives","alt":"Embryonic germ layers and tissue derivatives. This image shows the structure of the embryo in the third week of development. Under the image, three callouts list the different organ systems into which each germ layer develops.","src":"assets/human-biology/year11/y11-germ-layers.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/28-2-embryonic-development/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2909_Embryo_Week_3-02-1.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Compare ectoderm, mesoderm and endoderm with their illustrated derivatives. The germ-layer categories describe developmental origins, not three fully formed organ systems already present in an early embryo.","width":1447,"height":1252,"sourceCaption":"Figure 28.2.7 – Fates of Germ Layers in Embryo:  Following gastrulation of the embryo in the third week, embryonic cells of the ectoderm, mesoderm, and endoderm begin to migrate and differentiate into the cell lineages that will give rise to mature organs and organ systems in the infant."},"y11-menstrual-cycle":{"title":"Hormones, ovarian events and the uterine cycle","alt":"Hormones, ovarian events and the uterine cycle. The top panel of this image shows the stages in the follicular phase and how one follicle is selected at the end of this phase. The middle part of this image shows the ovarian cycle phases and the uterine cycle phases. The bottom panel shows the levels of different hormones as a function of time.","src":"assets/human-biology/year11/y11-menstrual-cycle.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/27-3-physiology-of-the-female-sexual-system/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/cdcdf2286ebcf71c2c109cbb44f5965ff258bf5a.jpeg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Align FSH, LH, oestrogen and progesterone changes with follicular development, ovulation, corpus luteum and endometrial changes. Treat the illustrated cycle as a model: cycle timing varies and ovulation is not always on calendar day 14.","width":619,"height":1059,"sourceCaption":"Figure 27.3.4 Hormone Levels in Ovarian and Menstrual Cycles The correlation of the hormone levels and their effects on the female reproductive system is shown in this timeline of the ovarian and menstrual cycles. The menstrual cycle begins at day one with the start of menses. Ovulation occurs around day 14 of a 28-day cycle, triggered by the LH surge."},"y11-recessive-inheritance":{"title":"Autosomal recessive inheritance: carrier parents","alt":"Autosomal recessive inheritance: carrier parents. In this figure, the offspring of a carrier father and carrier mother are shown. The first generation has one unaffected son, one affected daughter and one carrier son and one carrier daughter. The second generation cross shows seventy five percent unaffected and twenty five percent affected with cystic fibrosis.","src":"assets/human-biology/year11/y11-recessive-inheritance.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/28-7-patterns-of-inheritance/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2926_Autosomal_Recessive_Inheritance-new.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Identify the parental genotypes and possible offspring combinations. Distinguish genotype probability from affected-phenotype probability and state that probabilities apply independently to each conception under the model.","width":1900,"height":1029,"sourceCaption":"Figure 28.7.4 – Autosomal Recessive Inheritance:  The inheritance pattern of an autosomal recessive disorder with two carrier parents reflects a 3:1 probability of expression among offspring. (credit: U.S. National Library of Medicine)"},"y11-placenta":{"title":"Placental structure and maternal–fetal exchange","alt":"Placental structure and maternal–fetal exchange. This figure shows the location and structure of the placenta. The left panel shows a fetus in the womb. The right panel shows a magnified view of a small region including the placenta and the blood vessels.","src":"assets/human-biology/year11/y11-placenta.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/28-2-embryonic-development/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2910_The_Placenta-02.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Locate maternal blood spaces and fetal capillaries in chorionic villi. Trace exchange across the intervening barrier while distinguishing the two blood circulations; normal exchange does not require free mixing of maternal and fetal blood.","width":1900,"height":986,"sourceCaption":"Figure 28.2.8 – Cross-Section of the Placenta:  In the placenta, maternal and fetal blood components are conducted through the surface of the chorionic villi, but maternal and fetal bloodstreams never mix directly."},"y11-x-linked":{"title":"X-linked recessive inheritance","alt":"X-linked recessive inheritance. This figure shows the offspring from a carrier mother with the X-linked recessive inheritance.","src":"assets/human-biology/year11/y11-x-linked.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/28-7-patterns-of-inheritance/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2928_X-linked_Recessive_Inheritance-new.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Trace X-linked alleles through the illustrated family and gametes. State whether a risk is conditional on an offspring being male or female, or refers to all conceptions; those denominators differ.","width":1381,"height":1046,"sourceCaption":"Figure 28.7.6 – X-Linked Recessive Inheritance:  Given two parents in which the father is normal and the mother is a carrier of an X-linked recessive disorder, a son would have a 50 percent probability of being affected with the disorder, whereas daughters would either be carriers or entirely unaffected. (credit: U.S. National Library of Medicine)"},"y11-implantation":{"title":"Blastocyst implantation in the endometrium","alt":"Blastocyst implantation in the endometrium. This figure shows the different steps during implantation. The top panel shows how the blastocyst burrows into the endometrium. The middle panel shows the blastocyst completely surrounded by the endometrium. The bottom panel shows the implanted embryo growing in the uterus.","src":"assets/human-biology/year11/y11-implantation.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/28-2-embryonic-development/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2905_Implantation-1.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Trace the blastocyst attaching to and embedding in the uterine lining. Identify the trophoblast and inner cell mass, and explain why implantation is a later event than fertilisation.","width":1518,"height":1900,"sourceCaption":"Figure 28.2.3 – Implantation:  During implantation, the trophoblast cells of the blastocyst adhere to the endometrium and digest endometrial cells until it is attached securely."},"y11-fetal-circulation":{"title":"Fetal circulation and the placental route","alt":"Fetal circulation and the placental route. This figure shows a baby in the center of the image. To the left, is a panel showing the umbilical cord and how blood is supplied to the baby in the womb. Two panels on the right show the circulation of blood inside the baby’s body.","src":"assets/human-biology/year11/y11-fetal-circulation.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/28-3-fetal-development/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2025/08/2916_Fetal_Circulatory_System-02.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Trace blood through the umbilical vessels and identify ductus venosus, foramen ovale and ductus arteriosus. Explain how the placental circulation differs from postnatal lung-based gas exchange; oxygenation colours are a simplified model.","width":1900,"height":1656,"sourceCaption":"Figure 28.3.2 – Fetal Circulatory System:  The fetal circulatory system includes three shunts to divert blood from undeveloped and partially functioning organs, as well as blood supply to and from the placenta."},"y11-spermatogenesis":{"title":"Spermatogenesis: mitosis, meiosis and differentiation","alt":"Spermatogenesis: mitosis, meiosis and differentiation. This figure shows the steps in spermatogenesis. The left panel shows a flow chart that outlines the different steps in the formation of sperm. The right panel shows a micrograph with the cross section of a seminiferous tubule.","src":"assets/human-biology/year11/y11-spermatogenesis.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/27-4-physiology-of-the-male-sexual-system/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2019/10/b7768deb900fb73aec09dd5853a3c06518f273a6.jpeg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Trace spermatogonia through spermatocytes and spermatids to sperm. Identify where chromosome number is reduced and distinguish meiosis from the later structural differentiation of a spermatid.","width":822,"height":594,"sourceCaption":"Figure 27.4.1 Spermatogenesis (a) Mitosis of a spermatogonial stem cell involves a single cell division that results in two identical, diploid daughter cells (spermatogonia to primary spermatocyte). Meiosis has two rounds of cell division: primary spermatocyte to secondary spermatocyte, and then secondary spermatocyte to spermatid. This produces four haploid daughter cells (spermatids). (b) In this electron micrograph of a cross-section of a seminiferous tubule from a rat, the lumen is the light-shaded area in the center of the image. The location of the primary spermatocytes is near the basement membrane, and the early spermatids are approaching the lumen (tissue source: rat). EM × 900. (Micrograph provided by the Regents of University of Michigan Medical School © 2012)"},"y11-oogenesis":{"title":"Oogenesis and unequal meiotic divisions","alt":"Oogenesis and unequal meiotic divisions. This flowchart shows the formation of oocytes in the female. The top half of the flowchart is before birth and the bottom half is after puberty. A callout to the left also shows the eggs before and after sperm penetration.","src":"assets/human-biology/year11/y11-oogenesis.jpg","author":"OpenStax and Oregon State University Anatomy & Physiology contributors","source":"https://open.oregonstate.education/anatomy/chapter/27-3-physiology-of-the-female-sexual-system/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2019/07/cb3a51b134cfa417cf88f924fed1d8731ef8754f.jpeg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Resized where necessary and converted to JPEG; scientific image content retained.","guide":"Follow diploid precursors, meiotic stages, the large secondary oocyte and polar bodies. Explain why equal chromosome segregation does not require equal cytoplasm division; completion of the final meiotic division normally follows fertilisation.","width":690,"height":578,"sourceCaption":"Figure 27.3.1 Oogenesis The unequal cell division of oogenesis produces one to three polar bodies that later degrade, as well as a single haploid ovum, which is produced only if there is penetration of the secondary oocyte by a sperm cell."},"y11-pedigree":{"title":"Pedigree analysis: an autosomal recessive disorder","alt":"A four-generation labelled pedigree of alkaptonuria using squares and circles, affected and unaffected symbols, genotype labels and numbered people for inference.","src":"assets/human-biology/year11/y11-pedigree.jpg","author":"OpenStax Biology 2e contributors, 2018 edition, via Lumen Learning","source":"https://courses.lumenlearning.com/suny-osbiology2e/chapter/characteristics-and-traits/","imageSource":"https://s3-us-west-2.amazonaws.com/courses-images/wp-content/uploads/sites/3206/2018/05/03183054/Figure_12_02_11.jpg","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changes":"Converted to JPEG for display; scientific image content retained.","guide":"Read generations, relationship lines and the legend before inferring genotypes. Under the supplied autosomal-recessive model, affected people are aa; an unaffected parent of an affected child must carry a. Explain why an unaffected person can remain AA or Aa when the family evidence is insufficient. This figure concerns alkaptonuria and illustrates the analysis method, not every inherited condition.","sourceCaption":"OpenStax Figure 12.6 / earlier Figure 12.2.11: pedigree analysis for recessive alkaptonuria, retained in the 2018 CC BY 4.0 Lumen-hosted edition.","width":544,"height":478},"y11-karyotype":{"title":"Human karyotype: 22 autosomal pairs and X/Y","alt":"A human karyotype with chromosome pairs 1–22 and an X/Y complement arranged by size and banding pattern.","src":"assets/human-biology/year11/y11-karyotype.jpg","author":"National Human Genome Research Institute; reproduced in OpenStax / Oregon State University Anatomy & Physiology","source":"https://open.oregonstate.education/anatomy/chapter/28-7-patterns-of-inheritance/","imageSource":"https://open.oregonstate.education/app/uploads/sites/309/2019/07/2923_Male_Chromosomes.jpg","license":"CC BY-SA 4.0 (source textbook reproduction; original image credited to NHGRI)","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/","changes":"Converted to JPEG for display; scientific image content retained.","guide":"Count the 22 autosomal pairs and identify the X/Y complement. Compare homologous chromosomes by approximate size, centromere position and banding. A karyotype can reveal whole-chromosome number and some large structural changes; it does not establish the base sequence of every gene or exclude all genetic conditions. The image shows one typical chromosome complement, not every human variation.","sourceCaption":"Figure 28.7.1 – Chromosomal Complement of a Male. Original credit: National Human Genome Research Institute.","width":1900,"height":1453},"y11-enzyme-data":{"title":"Enzyme concentration and a reciprocal-time rate proxy","alt":"Synthetic enzyme investigation: relative enzyme concentration versus reciprocal mean endpoint time, with replicate-derived points.","src":"assets/human-biology/year11/y11-enzyme-data.png","author":"Learning Vault original synthetic teaching dataset and chart","source":"human-biology-year11-coverage.html","license":"CC BY 4.0","licenseUrl":"https://creativecommons.org/licenses/by/4.0/","changes":"Original plot; all values are explicitly synthetic.","guide":"Read both axes and the reciprocal-time units. Distinguish 1/mean time from each individual reciprocal, identify the overall trend and explain the assumption of an equivalent reaction endpoint. These are specified teaching data, not measurements you collected."}};for(const [key,value]of Object.entries(data)){root.HBFreshImages[key]=value;root.HBFreshImageGuides[key]=value.guide;}})(window);Object.assign(window.HBFreshImageGuides,{"membrane": "Identify the phospholipid bilayer, membrane proteins and other labelled components. Relate a hydrophobic barrier to simple diffusion and explain how channels or carriers change selective movement. A static diagram does not show the full fluid motion.", "osmosis": "Identify the selectively permeable barrier and compare solute conditions on both sides. Trace net water movement and explain how the gradient changes. The figure models water movement rather than active pumping of each molecule.", "mitosis": "Follow chromosome condensation, single alignment, sister separation and daughter-nucleus formation. Distinguish chromosome number from DNA amount and compare the stated context with meiosis II. A coloured teaching model does not show every cell-cycle control.", "crossing": "Identify paired homologues and non-sister chromatids. Trace an exchange of corresponding segments and explain how it changes allele combinations without generating a new allele for every exchange."});